SELECT s.Song_Name
FROM singer s
WHERE CAST(s.Age AS REAL) > (
    SELECT AVG(CAST(Age AS REAL))
    FROM singer
);

SELECT PetType, MAX(weight) AS max_weight
FROM Pets
GROUP BY PetType;

SELECT AVG(Age) AS avg_age
FROM Student
